import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _divide(n, d):
    assert n % d == 0, f"{n} is not divisible by {d}"
    return n // d


# ---------------------------------------------------------------------------
# Autograd-aware communication primitives
# ---------------------------------------------------------------------------
class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce gradient."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        if _world_size() == 1:
            return grad
        grad = grad.contiguous().clone()
        dist.all_reduce(grad, op=dist.ReduceOp.SUM)
        return grad


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        if _world_size() == 1:
            return x
        x = x.contiguous().clone()
        dist.all_reduce(x, op=dist.ReduceOp.SUM)
        return x

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take this rank's chunk of the last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        ws = _world_size()
        if ws == 1:
            return x
        chunk = _divide(x.shape[-1], ws)
        r = _rank()
        return x[..., r * chunk:(r + 1) * chunk].contiguous()

    @staticmethod
    def backward(ctx, grad):
        return _gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take this rank's chunk."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        ws = _world_size()
        if ws == 1:
            return grad
        chunk = _divide(grad.shape[-1], ws)
        r = _rank()
        return grad[..., r * chunk:(r + 1) * chunk].contiguous()


def _gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


# ---------------------------------------------------------------------------
# Layers
# ---------------------------------------------------------------------------
class ColumnParallelLinear(nn.Module):
    """Y = XA + b with A split along its output (column) dimension.

    Weight is stored in nn.Linear layout: (out_features, in_features), so each
    rank holds rows [rank*out_per, (rank+1)*out_per) of master_weight.
    The output is all-gathered along the last dimension.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.output_size_per_partition = _divide(out_features, self.world_size)

        assert tuple(master_weight.shape) == (out_features, in_features)
        start = self.rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[start:end, :].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(self.output_size_per_partition,
                            dtype=shard.dtype, device=shard.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out)


class RowParallelLinear(nn.Module):
    """Y = XA + b with A split along its input (row) dimension.

    Weight is stored in nn.Linear layout: (out_features, in_features), so each
    rank holds columns [rank*in_per, (rank+1)*in_per) of master_weight.
    Partial outputs are all-reduced (summed); bias is full on every rank and
    added once after the reduction.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.input_size_per_partition = _divide(in_features, self.world_size)

        assert tuple(master_weight.shape) == (out_features, in_features)
        start = self.rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[:, start:end].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(out_features, dtype=shard.dtype, device=shard.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already
        # partitioned input.
        if x.shape[-1] == self.input_size_per_partition:
            x_local = x
        elif x.shape[-1] == self.in_features:
            x_local = _ScatterToParallelRegion.apply(x)
        else:
            raise ValueError(
                f"Unexpected input last dim {x.shape[-1]}; expected "
                f"{self.in_features} or {self.input_size_per_partition}"
            )
        partial = F.linear(x_local, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
